#!/bin/sh
mkdir -p /app/data
trap 'kill $(cat /tmp/chat.pids 2>/dev/null) 2>/dev/null; exit 0' TERM INT
: > /tmp/chat.pids
for n in 0 1 2; do PORT=$((8000+n)) NODE_ID=$n python3 /app/server.py & echo $! >> /tmp/chat.pids; done
python3 /app/irc.py & echo $! >> /tmp/chat.pids
wait
SH
chmod +x /app/start.sh
cat > /app/irc.py <<'PY'
import socket,threading,json,sqlite3,os,time
DB='/app/data/chat.db'; clients=[]; used=set()
def send(c,s): c.send((s+'\r\n').encode())
def run(c):
 token=None;nick=None;uid=None;joined={}
 try:
  while 1:
   z=c.recv(4096)
   if not z:break
   for line in z.decode(errors='ignore').splitlines():
    p=line.split(); cmd=p[0].upper() if p else ''
    if cmd=='PASS':
     token=p[1] if len(p)>1 else ''
     with sqlite3.connect(DB) as d:
      q=d.execute('SELECT user_id FROM tokens WHERE token=?',(token,)).fetchone()
     if not q:send(c,':irc 464 * :Password incorrect');token=None
     else:uid=q[0]
    elif cmd=='NICK':
     if p[1] in used:send(c,':irc 433 * '+p[1]+' :Nickname in use')
     else:nick=p[1]
    elif cmd=='USER' and token and uid and nick:
     used.add(nick);clients.append((c,uid,nick,joined));send(c,':irc 001 '+nick+' :Welcome');send(c,':irc 002 '+nick+' :Your host');send(c,':irc 003 '+nick+' :Created');send(c,':irc 004 '+nick+' irc');send(c,':irc 005 '+nick+' :CHANTYPES=#');send(c,':irc 422 '+nick+' :MOTD File Missing')
    elif cmd=='PING':send(c,':irc PONG irc :'+(p[-1].lstrip(':') if p else ''))
    elif cmd=='QUIT':return
    elif cmd in ('PONG','NAMES','WHO','LIST','TOPIC','MODE'): pass
    elif cmd=='JOIN' and len(p)>1:
     name=p[1]; q=name[1:].split('/') if name.startswith('#') else []
     with sqlite3.connect(DB) as d: ch=d.execute('SELECT c.id,w.slug,c.name FROM channels c JOIN workspaces w ON w.id=c.workspace_id WHERE w.slug=? AND c.name=?',(q[0],q[1] if len(q)>1 else '')).fetchone() if len(q)==2 else None
     if not ch:send(c,':irc 403 '+nick+' '+name+' :No such channel');continue
     joined[name]=ch[0];send(c,':'+nick+'!user@host JOIN '+name);send(c,':irc 353 '+nick+' = '+name+' :'+nick);send(c,':irc 366 '+nick+' '+name+' :End')
    elif cmd=='PRIVMSG' and len(p)>2:
     name=p[1];body=' '.join(p[2:]).lstrip(':');cid=joined.get(name)
     if cid:
      with sqlite3.connect(DB) as d:
       d.execute('INSERT INTO messages(channel_id,author_id,body,created) VALUES(?,?,?,?)',(cid,uid,body,__import__('datetime').datetime.utcnow().isoformat()+'Z'))
      for x in clients:
       if x[0] is not c and name in x[3]:send(x[0],':'+nick+'!user@host PRIVMSG '+name+' :'+body)
    elif cmd:send(c,':irc 421 '+(p[0] if p else '')+' :Unknown command')
 finally:
  if nick:used.discard(nick)
  if (c,uid,nick,joined) in clients:clients.remove((c,uid,nick,joined))
  c.close()
s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind(('0.0.0.0',6667));s.listen()
while 1:
 c,_=s.accept();threading.Thread(target=run,args=(c,),daemon=True).start()
